// Package i18n: minimal lookup-table style admin UI translation.
//
// Design:
//   - Languages = ja (default) / en (= add to the dict map when scaling up gradually).
//   - lang resolves via the cookie `unmask_locale`.  Falls back to Accept-Language.
//   - T(lang, key) returns the translation.  Missing keys fall back ja → key.
//   - Placeholders are %s / %d (= fmt.Sprintf style).  Use Tf(lang, key, args...).
//   - ja is both "the final fallback for missing keys" and "source of truth," so it always carries every key.
package i18n

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
)

// Lang: enum-like.  Holding it as a string makes it easy to add zh-CN / ko etc. later.
type Lang string

const (
	LangJA Lang = "ja"
	LangEN Lang = "en"
)

// SupportedLangs: for the picker UI.  Slice to preserve ordering.
var SupportedLangs = []Lang{LangJA, LangEN}

// NativeName: the language's own name, shown in pickers so a reader of
// language X can recognise their own option without speaking the page's
// current language.  Add an entry here whenever a new lang is added to
// SupportedLangs.  Unknown codes fall back to the code itself.
var NativeName = map[Lang]string{
	LangJA: "日本語",
	LangEN: "English",
}

// NameOf: defensive lookup so callers don't have to handle missing entries.
func NameOf(l Lang) string {
	if n, ok := NativeName[l]; ok {
		return n
	}
	return string(l)
}

// CookieName: name of the locale cookie.  The picker JS writes the same name.
const CookieName = "unmask_locale"

